public(package) fun handle_collateral_auto_deleverage<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;

    let collateral = type_name::with_defining_ids<CollateralType>();

    // load the time locked adl params
    let adl_registry = self.adl_registry<MarketType>();
    let timelock = *adl_registry.get_collateral_deleverage(collateral);

    // refresh obligation
    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    // obtain the emode group
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());

    // make sure the Collateral Type is indeed a collateral, otherwise revert
    let collateral_setting = emode_group.borrow_emode(collateral).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let max_liquidation_incentive = collateral_setting.liquidation_incentive();

    // force interest update for the collateral asset
    let asset = self.assets.load_mut_by_type(collateral);
    accrue_interest<MarketType>(collateral, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let total_deposit = self.reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().floor();
    let collateral_params = timelock.inner();
    collateral_params.ensure_limit_breached(total_deposit);
    let activation_time = timelock.get_secs_since_activation(clock);

    let liquidation_params = LiquidationParams {
